2	 * Shared utilities for agentic providers (Claude Agent SDK, OpenCode SDK, etc.)
3	 *
4	 * These utilities handle common functionality needed by coding agent providers:
5	 * - Working directory fingerprinting for cache key generation
6	 * - Response caching with fingerprint support
7	 */
8	
9	import crypto from 'crypto';
10	import fs from 'fs';
11	import path from 'path';
12	
13	import dedent from 'dedent';
14	import { getCache, isCacheEnabled } from '../cache';
15	import logger from '../logger';
