function extractJsonFromFencedBlock(text: string): unknown {
  // Match ```json ... ``` or ``` ... ``` fenced blocks
  const fenceRegex = /```(?:json)?\s*\n?([\s\S]*?)```/gi;
  let match: RegExpExecArray | null;
  while ((match = fenceRegex.exec(text)) !== null) {
